export declare const basicTheme = "/* \u9ED8\u8BA4\u6837\u5F0F\uFF0C\u6700\u4F73\u5B9E\u8DF5 */\n\n/* \u5168\u5C40\u5C5E\u6027 */\n#wemd {\n  font-size: 16px;\n  color: #000000;\n  padding: 0 8px;\n  line-height: 1.6;\n  word-spacing: 0px;\n  letter-spacing: 0px;\n  word-break: break-word;\n  word-wrap: break-word;\n  text-align: left;\n  font-family: Optima-Regular, Optima, PingFangSC-light, PingFangTC-light, 'PingFang SC', 'Microsoft YaHei', '\u5FAE\u8F6F\u96C5\u9ED1', 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;\n}\n\n/* \u6BB5\u843D */\n#wemd p {\n  font-size: 16px;\n  margin: 0;\n  line-height: 26px;\n  color: #000000;\n}\n\n/* \u6807\u9898 */\n#wemd h1,\n#wemd h2,\n#wemd h3,\n#wemd h4,\n#wemd h5,\n#wemd h6 {\n  margin-top: 30px;\n  margin-bottom: 15px;\n  padding: 0px;\n  font-weight: bold;\n  color: #000000;\n}\n#wemd h1 {\n  font-size: 24px;\n}\n#wemd h2 {\n  font-size: 22px;\n}\n#wemd h3 {\n  font-size: 20px;\n}\n#wemd h4 {\n  font-size: 18px;\n}\n#wemd h5 {\n  font-size: 16px;\n}\n#wemd h6 {\n  font-size: 16px;\n}\n\n#wemd h1 .prefix,\n#wemd h2 .prefix,\n#wemd h3 .prefix,\n#wemd h4 .prefix,\n#wemd h5 .prefix,\n#wemd h6 .prefix {\n  display: none;\n}\n\n#wemd h1 .suffix,\n#wemd h2 .suffix,\n#wemd h3 .suffix,\n#wemd h4 .suffix,\n#wemd h5 .suffix,\n#wemd h6 .suffix {\n  display: none;\n}\n\n/* \u5217\u8868 */\n#wemd ul,\n#wemd ol {\n  margin-top: 8px;\n  margin-bottom: 8px;\n  padding-left: 25px;\n  color: #000000;\n}\n#wemd ul {\n  list-style-type: disc;\n}\n#wemd ul ul {\n  list-style-type: square;\n}\n\n#wemd ol {\n  list-style-type: decimal;\n}\n\n#wemd li section {\n  margin-top: 5px;\n  margin-bottom: 5px;\n  line-height: 26px;\n  text-align: left;\n  color: #010101; /* \u4F7F\u7528\u63A5\u8FD1\u9ED1\u8272\u7684 HEX\uFF0C\u907F\u514D\u5FAE\u4FE1\u541E\u6389\u7EAF\u9ED1\u8272 */\n  font-weight: 500;\n}\n\n/* \u5F15\u7528 */\n#wemd blockquote {\n  border: none;\n}\n\n#wemd .multiquote-1 {\n  display: block;\n  font-size: 0.9em;\n  overflow: auto;\n  overflow-scrolling: touch;\n  border-left: 3px solid rgba(0, 0, 0, 0.4);\n  background: rgba(0, 0, 0, 0.05);\n  color: #6a737d;\n  padding-top: 10px;\n  padding-bottom: 10px;\n  padding-left: 20px;\n  padding-right: 10px;\n  margin-bottom: 20px;\n  margin-top: 20px;\n}\n\n#wemd .multiquote-1 p {\n  margin: 0px;\n  color: #000000;\n  line-height: 26px;\n}\n\n#wemd .multiquote-2 {\n  box-shadow: 1px 1px 10px rgba(0,0,0,0.2);\n  padding: 20px;\n  margin-bottom: 20px;\n  margin-top: 20px;\n}\n\n#wemd .multiquote-3 {\n  box-shadow: 1px 1px 10px rgba(0,0,0,0.2);\n  padding: 20px;\n  margin-bottom: 20px;\n  margin-top: 20px;\n}\n\n#wemd .multiquote-3 p {\n  text-align: center;\n}\n\n#wemd .multiquote-3 h3 {\n  text-align: center;\n}\n\n#wemd .table-of-contents a {\n  border: none;\n  color: #000000;\n  font-weight: normal;\n}\n\n/* \u94FE\u63A5 */\n#wemd a {\n  text-decoration: none;\n  color: #1e6bb8;\n  word-wrap: break-word;\n  font-weight: bold;\n  border-bottom: 1px solid #1e6bb8;\n}\n\n/* \u52A0\u7C97 */\n#wemd strong {\n  font-weight: bold;\n  color: #000000;\n}\n\n/* \u659C\u4F53 */\n#wemd em {\n  font-style: italic;\n  color: #000000;\n}\n\n/* \u52A0\u7C97\u659C\u4F53 */\n#wemd em strong {\n  font-weight: bold;\n  color: #000000;\n}\n\n/* \u5220\u9664\u7EBF */\n#wemd del {\n  font-style: italic;\n  color: #000000;\n}\n\n/* \u4E0B\u5212\u7EBF */\n#wemd u {\n  text-decoration: underline;\n  text-underline-offset: 0.18em;\n  text-decoration-thickness: 1px;\n}\n\n/* \u5206\u9694\u7EBF */\n#wemd hr {\n  height: 1px;\n  margin: 0;\n  margin-top: 10px;\n  margin-bottom: 10px;\n  border: none;\n  border-top: 1px solid black;\n}\n\n/* \u4EE3\u7801\u5757\u5BB9\u5668 */\n#wemd pre {\n  margin-top: 10px;\n  margin-bottom: 10px;\n  overflow-x: auto;\n  -webkit-overflow-scrolling: touch;\n}\n\n#wemd pre.custom {\n  padding: 0;\n  border-radius: 6px;\n  overflow: hidden;\n  overflow-x: auto;\n}\n\n#wemd pre code {\n  display: block;\n  font-family: Operator Mono, Consolas, Monaco, Menlo, monospace;\n  border-radius: 0px;\n  font-size: 12px;\n  white-space: pre;\n  min-width: max-content;\n  -webkit-overflow-scrolling: touch;\n}\n\n#wemd pre code span {\n  line-height: 26px;\n}\n\n/* \u884C\u5185\u4EE3\u7801 */\n#wemd p code,\n#wemd li code,\n#wemd td code,\n#wemd th code {\n  font-size: 14px;\n  word-wrap: break-word;\n  padding: 2px 4px;\n  border-radius: 4px;\n  margin: 0 2px;\n  color: #1e6bb8;\n  background-color: rgba(27,31,35,.05);\n  font-family: Operator Mono, Consolas, Monaco, Menlo, monospace;\n  word-break: break-all;\n}\n\n/* \u56FE\u7247 */\n#wemd img {\n  display: block;\n  margin: 0 auto;\n  max-width: 100%;\n}\n\n/* \u56FE\u7247 */\n#wemd figure {\n  margin: 0;\n  margin-top: 10px;\n  margin-bottom: 10px;\n}\n\n/* \u56FE\u7247\u63CF\u8FF0\u6587\u5B57 */\n#wemd figcaption {\n  margin-top: 5px;\n  text-align: center;\n  color: #888;\n  font-size: 14px;\n}\n\n\n/* \u8868\u683C\u5BB9\u5668 */\n#wemd .table-container{\n  overflow-x: auto;\n}\n\n/* \u8868\u683C */\n#wemd table {\n  display: table;\n  text-align: left;\n}\n#wemd tbody {\n  border: 0;\n}\n\n#wemd table tr {\n  border: 0;\n  border-top: 1px solid #ccc;\n  background-color: #ffffff;\n}\n\n#wemd table tr:nth-child(2n) {\n  background-color: #F8F8F8;\n}\n\n#wemd table tr th,\n#wemd table tr td {\n  font-size: 16px;\n  border: 1px solid #ccc;\n  padding: 5px 10px;\n  text-align: left;\n}\n\n#wemd table tr th {\n  font-weight: bold;\n  background-color: #f0f0f0;\n}\n\n/* \u8868\u683C\u6700\u5C0F\u5217\u5BBD4\u4E2A\u6C49\u5B57 */\n#wemd table tr th:nth-of-type(n),\n#wemd table tr td:nth-of-type(n){\n  min-width:85px;\n}\n\n#wemd .footnote-word {\n  color: #1e6bb8;\n  font-weight: bold;\n}\n\n#wemd .footnote-ref {\n  color: #1e6bb8;\n  font-weight: bold;\n}\n\n#wemd .footnote-item {\n  display: flex;\n}\n\n#wemd .footnote-num {\n  display: inline;\n  width: 10%; /*\u795E\u5947\uFF0C50px\u5C31\u4E0D\u53EF\u4EE5*/\n  background: none;\n  font-size: 80%;\n  opacity: 0.6;\n  line-height: 26px;\n  font-family: ptima-Regular, Optima, PingFangSC-light, PingFangTC-light, 'PingFang SC', Cambria, Cochin, Georgia, Times, 'Times New Roman', serif;\n}\n\n#wemd .footnote-item p {\n  display: inline;\n  font-size: 14px;\n  width: 90%;\n  padding: 0px;\n  margin: 0;\n  line-height: 26px;\n  color: #000000;\n  word-break:break-all;\n  width: calc(100%-50)\n}\n\n#wemd sub, sup {\n  line-height: 0;\n}\n\n#wemd .footnotes-sep:before {\n  content: \"\u53C2\u8003\u8D44\u6599\";\n  display: block;\n}\n\n/* \u89E3\u51B3\u516C\u5F0F\u95EE\u9898 */\n#wemd .block-equation {\n  display:block;\n  text-align: center;\n  overflow: auto;\n  display: block;\n  -webkit-overflow-scrolling: touch;\n}\n\n#wemd .block-equation > svg {\n  max-width: 300% !important;\n  -webkit-overflow-scrolling: touch;\n}\n\n#wemd .inline-equation {\n}\n\n#wemd .inline-equation > svg {\n}\n\n#wemd .imageflow-layer1 {\n  margin-top: 1em;\n  margin-bottom: 0.5em;\n  white-space: normal;\n  border: 0px none;\n  padding: 0px;\n  overflow: hidden;\n}\n\n#wemd .imageflow-layer2 {\n  white-space: nowrap;\n  width: 100%;\n  overflow-x: scroll;\n}\n\n#wemd .imageflow-layer3 {\n  display: inline-block;\n  word-wrap: break-word;\n  white-space: normal;\n  vertical-align: top;\n  width: 80%;\n  margin-right: 10px;\n  flex-shrink: 0;\n}\n\n#wemd .imageflow-img {\n  display: block;\n  width: 100%;\n  height: auto;\n  max-height: 300px;\n  object-fit: contain;\n  border-radius: 4px;\n}\n\n#wemd .imageflow-caption {\n  text-align: center;\n  margin-top: 0px;\n  padding-top: 0px;\n  color: #888;\n}\n\n#wemd .nice-suffix-juejin-container {\n  margin-top: 20px !important;\n}\n\n#wemd figure a {\n  border: none;\n}\n\n#wemd figure a img {\n  margin: 0px;\n}\n\n#wemd figure {\n  display:flex;\n  flex-direction: column;\n  justify-content: center;\n  align-items: center;\n}\n\n/* \u56FE\u7247\u94FE\u63A5\u5D4C\u5957 */\n#wemd figure a {\n  display: flex;\n  justify-content: center;\n  align-items: center;\n}\n\n/* \u56FE\u7247\u94FE\u63A5\u5D4C\u5957\uFF0C\u56FE\u7247\u89E3\u91CA */\n#wemd figure a + figcaption {\n  display: flex;\n  justify-content: center;\n  align-items: center;\n  width: 100%;\n  margin-top: -35px;\n  background: rgba(0,0,0,0.7);\n  color: #ffffff;\n  line-height: 35px;\n  z-index: 20;\n}\n\n#wemd .callout {\n  margin: 24px 0;\n  padding: 18px 20px;\n  border-radius: 16px;\n  border: 1px solid #e2e8f0;\n  background: #ffffff;\n  box-shadow: 0 12px 25px rgba(15, 23, 42, 0.08);\n}\n\n#wemd .callout-title {\n  font-weight: 600;\n  margin-bottom: 8px;\n  display: flex;\n  align-items: center;\n  gap: 0;\n  letter-spacing: 0.05em;\n}\n\n#wemd .callout-icon { margin-right: 8px;\n  font-size: 18px;\n}\n\n#wemd .callout-note { border-left: 4px solid #6366f1; background: #f5f5ff; }\n#wemd .callout-tip { border-left: 4px solid #10b981; background: #ecfdf5; }\n#wemd .callout-important { border-left: 4px solid #8b5cf6; background: #f5f3ff; }\n#wemd .callout-warning { border-left: 4px solid #f59e0b; background: #fffbeb; }\n#wemd .callout-caution { border-left: 4px solid #ef4444; background: #fff5f5; }\n\n\n#wemd .task-list-item {\n  list-style: none;\n  margin-left: -1.2em;\n  margin-bottom: 6px;\n  display: flex;\n  gap: 0;\n  align-items: flex-start;\n}\n\n#wemd .task-list-item input[type='checkbox'] {\n  margin-top: 4px;\n  pointer-events: none;\n}\n";
